private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (i < bb.limit()) {
        byte b = bb.get(i);
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            if (i + 1 >= bb.limit()) break;
            byte b2 = bb.get(i + 1);
            if ((b2 & 0xC0) != 0x80) break;
            char c = (char) (((b & 0x1F) << 6) | (b2 & 0x3F));
            sb.append(c);
            i += 2;
        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            if (i + 2 >= bb.limit()) break;
            byte b2 = bb.get(i + 1);
            byte b3 = bb.get(i + 2);
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) break;
            char c = (char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
            sb.append(c);
            i += 3;
        } else if ((b & 0xF8) == 0xF0) {
            // Four-byte character
            if (i + 3 >= bb.limit()) break;
            byte b2 = bb.get(i + 1);
            byte b3 = bb.get(i + 2);
            byte b4 = bb.get(i + 3);
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) break;
            int codePoint = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
            if (codePoint >= 0x10000 && codePoint <= 0x10FFFF) {
                sb.append(Character.toChars(codePoint));
            }
            i += 4;
        } else {
            // Invalid UTF-8 sequence, skip this byte
            i++;
        }
    }
    return i;
}

