private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    if (size == 0) {
        return; // No need to enlarge if no additional space is required
    }
    int currentCapacity = (buffer == null) ? 0 : buffer.length;
    int neededCapacity = currentCapacity + size;
    if (neededCapacity > currentCapacity) {
        int newCapacity = Math.max(neededCapacity, currentCapacity * 2);
        byte[] newBuffer = new byte[newCapacity];
        if (buffer != null) {
            System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
        }
        buffer = newBuffer;
    }
}

