protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    final long FETCH_DATA_DURATION = 3600000; // Example value, assuming FETCH_DATA_DURATION is 1 hour in milliseconds

    if (start >= end) {
        throw new IllegalArgumentException("Start time must be before end time.");
    }

    while (start < end) {
        long nextStart = Math.min(start + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(start, nextStart));
        start = nextStart;
    }

    return timeRanges;
}

