static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    if (timeBucket < 10000000 || timeBucket > 99991231) {
        throw new IllegalArgumentException("timeBucket must be a valid date in the format YYYYMMDD");
    }

    int year = (int) (timeBucket / 10000);
    int monthDay = (int) (timeBucket % 10000);
    int month = monthDay / 100;
    int day = monthDay % 100;

    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket");
    }

    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    // Check for leap year
    if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
        daysInMonth[1] = 29;
    }

    if (day < 1 || day > daysInMonth[month - 1]) {
        throw new IllegalArgumentException("Invalid day in timeBucket");
    }

    // Calculate the day of the year
    int dayOfYear = 0;
    for (int i = 0; i < month - 1; i++) {
        dayOfYear += daysInMonth[i];
    }
    dayOfYear += day;

    // Calculate the new day of the year
    int newDayOfYear = (dayOfYear / dayStep) * dayStep;
    if (newDayOfYear == 0) {
        newDayOfYear = dayStep;
    }

    // Calculate the new month and day
    int newMonth = 0;
    int daysCounted = 0;
    while (newMonth < 12 && daysCounted + daysInMonth[newMonth] < newDayOfYear) {
        daysCounted += daysInMonth[newMonth];
        newMonth++;
    }

    int newDay = newDayOfYear - daysCounted;

    // Reconstruct the new time bucket
    return year * 10000L + (newMonth + 1) * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length specified");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len) {
                char nextChar = str.charAt(i + 1);
                if (Character.isLowSurrogate(nextChar)) {
                    size += 4; // surrogate pair
                    i++; // skip the next character as it's part of the surrogate pair
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair at index " + i);
                }
            } else {
                throw new IllegalArgumentException("Incomplete surrogate pair at index " + i);
            }
        } else {
            size += 3;
        }
    }
    return size;
}

