public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteOffset < 0 || (byteArrayValue != null && byteOffset > byteArrayValue.length - byteLength)) {
        throw new IndexOutOfBoundsException("Invalid byteOffset or byteLength");
    }

    if (byteArrayValue == null) {
        ensureCapacity(byteLength);
        for (int i = 0; i < byteLength; i++) {
            data[count++] = 0;
        }
    } else {
        ensureCapacity(byteLength);
        System.arraycopy(byteArrayValue, byteOffset, data, count, byteLength);
        count += byteLength;
    }

    return this;
}

private void ensureCapacity(final int additionalCapacity) {
    if (count + additionalCapacity > data.length) {
        int newSize = (data.length << 1) + additionalCapacity;
        byte[] newData = new byte[newSize];
        System.arraycopy(data, 0, newData, 0, count);
        data = newData;
    }
}

