private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    int index = 0;
    char c = descriptor.charAt(index);

    if (c == '(') {
        // Method descriptor
        index++;
        while (descriptor.charAt(index) != ')') {
            c = descriptor.charAt(index);
            index += popType(c);
        }
        index++; // Move past ')'
        // Now handle return type, but since pop is only for arguments, we ignore it
    } else {
        // Field descriptor
        popType(c);
    }
}

private int popType(char c) {
    switch (c) {
        case 'B':
        case 'C':
        case 'I':
        case 'S':
        case 'Z':
        case 'F':
            return 1; // Single slot
        case 'D':
        case 'J':
            return 2; // Double slot
        case 'L':
            // Object type, find end of class name
            while (c != ';') {
                c = descriptor.charAt(++index);
            }
            return 1; // Single slot
        case '[':
            // Array type, skip to type
            do {
                c = descriptor.charAt(++index);
            } while (c == '[');
            return popType(c); // Recursively pop type
        default:
            throw new IllegalArgumentException("Invalid descriptor character: " + c);
    }
}

