    if (len == 0) {
        return; // No bytes to write, return early
    }
    // Ensure there is enough space in the buf array
    if (count + len > buf.length) {
        buf = Arrays.copyOf(buf, Math.max(buf.length << 1, count + len));
    }
    System.arraycopy(b, off, buf, count, len);
    count += len;
}

