public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < length) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 'b':
                        result.append('\b');
                        i++;
                        break;
                    case 't':
                        result.append('\t');
                        i++;
                        break;
                    case 'n':
                        result.append('\n');
                        i++;
                        break;
                    case 'f':
                        result.append('\f');
                        i++;
                        break;
                    case 'r':
                        result.append('\r');
                        i++;
                        break;
                    case '"':
                        result.append('\"');
                        i++;
                        break;
                    case '\'':
                        result.append('\'');
                        i++;
                        break;
                    case '\\':
                        result.append('\\');
                        i++;
                        break;
                    default:
                        // If it's not a recognized escape sequence, just append the backslash and the next character
                        result.append(c);
                        break;
                }
            } else {
                // If a backslash is the last character, just append it
                result.append(c);
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

