private int removeUnusedNodesRecursively(CategoryNode node) {
    if (node == null) {
        return 0;
    }

    int removedCount = 0;
    List<CategoryNode> childrenToRemove = new ArrayList<>();

    for (CategoryNode child : node.getChildren()) {
