final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try {
        if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
            throw new IndexOutOfBoundsException("constantPoolEntryIndex out of bounds");
        }
        if (charBuffer == null) {
            throw new IllegalArgumentException("charBuffer cannot be null");
        }

        int utf8Length = (classFileBuffer[constantPoolEntryIndex] & 0xFF) << 8
                       | (classFileBuffer[constantPoolEntryIndex + 1] & 0xFF);
        int offset = 2; // Skip the length bytes
        int charIndex = 0;

        while (utf8Length > 0) {
            int b1 = classFileBuffer[constantPoolEntryIndex + offset++] & 0xFF;
            if (b1 < 0x80) {
                // Single byte encoding
                charBuffer[charIndex++] = (char) b1;
                utf8Length--;
            } else if ((b1 & 0xE0) == 0xC0) {
                // Two byte encoding
                int b2 = classFileBuffer[constantPoolEntryIndex + offset++] & 0xFF;
                if ((b2 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Malformed UTF-8 sequence");
                }
                charBuffer[charIndex++] = (char) (((b1 & 0x1F) << 6) | (b2 & 0x3F));
                utf8Length -= 2;
            } else if ((b1 & 0xF0) == 0xE0) {
                // Three byte encoding
                int b2 = classFileBuffer[constantPoolEntryIndex + offset++] & 0xFF;
                int b3 = classFileBuffer[constantPoolEntryIndex + offset++] & 0xFF;
                if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Malformed UTF-8 sequence");
                }
                charBuffer[charIndex++] = (char) (((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
                utf8Length -= 3;
            } else {
                throw new IllegalArgumentException("Malformed UTF-8 sequence");
            }
        }
        return new String(charBuffer, 0, charIndex);
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Insufficient data in classFileBuffer for UTF-8 at index " + constantPoolEntryIndex);
    }
}

