protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    Map<V, V> predecessors = new HashMap<>();
    V startVertex = null;
    V endVertex = null;

    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (startVertex == null) {
            startVertex = source;
        }
        if (predecessors.containsKey(target)) {
            throw new IllegalArgumentException("Provided tour is not a valid graph path");
        }
        predecessors.put(target, source);
        endVertex = target;
    }

    if (!predecessors.containsKey(startVertex)) {
        throw new IllegalArgumentException("Provided tour is not a valid graph path");
    }

    List<E> pathEdges = new ArrayList<>();
    List<V> pathVertices = new ArrayList<>();
    double pathWeight = 0.0;

    V currentVertex = endVertex;
    while (currentVertex != null) {
        pathVertices.add(0, currentVertex);
        if (predecessors.containsKey(currentVertex)) {
            E edge = graph.getEdge(predecessors.get(currentVertex), currentVertex);
            pathEdges.add(0, edge);
            pathWeight += graph.getEdgeWeight(edge);
        }
        currentVertex = predecessors.get(currentVertex);
    }

    return new GraphPathImpl<>(graph, startVertex, pathEdges, pathWeight);
}

