        }

        if (current.next != null) {
            current.next.prev = current.prev;
        } else {
            list.tail = current.prev; // Update tail if necessary
        }

        // Add current to this list
        current.prev = this.tail;
        current.next = null;

        if (this.tail != null) {
            this.tail.next = current;
        } else {
            this.head = current; // This list was empty, set new head
