private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    // Check if the descriptor is a method descriptor (starts with '(')
    if (descriptor.charAt(0) == '(') {
        int endIndex = descriptor.indexOf(')');
        if (endIndex == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String argumentTypes = descriptor.substring(1, endIndex);
        int index = 0;
        while (index < argumentTypes.length()) {
            char c = argumentTypes.charAt(index);
            switch (c) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                    // These are all single-slot types
                    index++;
                    break;
                case 'D': case 'J':
                    // These are double-slot types
                    index += 2;
                    break;
                case 'L':
                    // Object types, skip until ';'
                    index = argumentTypes.indexOf(';', index) + 1;
                    if (index == 0) {
                        throw new IllegalArgumentException("Invalid method descriptor: missing ';'");
                    }
                    break;
                case '[':
                    // Array types, skip to the end of the array descriptor
                    do {
                        index++;
                    } while (index < argumentTypes.length() && argumentTypes.charAt(index) == '[');
                    if (index < argumentTypes.length() && (argumentTypes.charAt(index) == 'L')) {
                        index = argumentTypes.indexOf(';', index) + 1;
                        if (index == 0) {
                            throw new IllegalArgumentException("Invalid method descriptor: missing ';'");
                        }
                    } else if (index >= argumentTypes.length() || (argumentTypes.charAt(index) != 'B' && argumentTypes.charAt(index) != 'C' && argumentTypes.charAt(index) != 'D' && argumentTypes.charAt(index) != 'F' && argumentTypes.charAt(index) != 'I' && argumentTypes.charAt(index) != 'J' && argumentTypes.charAt(index) != 'S' && argumentTypes.charAt(index) != 'Z')) {
                        throw new IllegalArgumentException("Invalid method descriptor: invalid array element type");
                    } else {
                        index++;
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid method descriptor: invalid type character '" + c + "'");
            }
        }
    } else {
        // Handle field descriptor
        switch (descriptor.charAt(0)) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                // Single-slot types
                break;
            case 'D': case 'J':
                // Double-slot types
                break;
            case 'L':
                // Object types, check for proper ending
                if (descriptor.charAt(descriptor.length() - 1) != ';') {
                    throw new IllegalArgumentException("Invalid field descriptor: missing ';'");
                }
                break;
            case '[':
                // Array types
                int index = 1;
                while (index < descriptor.length() && descriptor.charAt(index) == '[') {
                    index++;
                }
                if (index < descriptor.length() && descriptor.charAt(index) == 'L') {
                    if (descriptor.charAt(descriptor.length() - 1) != ';') {
                        throw new IllegalArgumentException("Invalid field descriptor: missing ';'");
                    }
                } else if (index >= descriptor.length() || (descriptor.charAt(index) != 'B' && descriptor.charAt(index) != 'C' && descriptor.charAt(index) != 'D' && descriptor.charAt(index) != 'F' && descriptor.charAt(index) != 'I' && descriptor.charAt(index) != 'J' && descriptor.charAt(index) != 'S' && descriptor.charAt(index) != 'Z')) {
                    throw new IllegalArgumentException("Invalid field descriptor: invalid array element type");
                }
                break;
            default:
                throw new IllegalArgumentException("Invalid field descriptor: invalid type character '" + descriptor.charAt(0) + "'");
        }
    }
}

