public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non-null");
    }

    // Normalize the input paths by trimming and removing trailing slashes
    path = path.trim().replaceAll("/+$", "");
    relativePath = relativePath.trim();

    // Split the relative path into segments
    String[] segments = relativePath.split("/");

    // Use a stack to process the path segments
    Stack<String> pathStack = new Stack<>();
    for (String segment : path.split("/")) {
        if (!segment.isEmpty()) {
            pathStack.push(segment);
        }
    }

    for (String segment : segments) {
        if (segment.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop();
            }
        } else if (!segment.equals(".") && !segment.isEmpty()) {
            pathStack.push(segment);
        }
    }

    // Build the resulting path from the stack
    StringBuilder result = new StringBuilder();
    while (!pathStack.isEmpty()) {
        result.insert(0, pathStack.pop());
        if (!pathStack.isEmpty()) {
            result.insert(0, "/");
        }
    }

    return result.toString();
}

