        throw new IllegalArgumentException("Invalid file: " + file);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges cannot be null or empty");
    }

    List<ThreadSnapshot> allSnapshots = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            // Assuming each line represents a ThreadSnapshot and can be parsed into one
            ThreadSnapshot snapshot = parseThreadSnapshot(line);
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (snapshot.getTimestamp() >= range.getStartTime() && snapshot.getTimestamp() <= range.getEndTime()) {
                    allSnapshots.add(snapshot);
                    break; // No need to check other ranges if one matches
                }
            }
        }
    } catch (IOException e) {
        throw new IOException("Error reading from file: " + file.getName(), e);
    }

    return allSnapshots;
}

